         ft_var_to_normalized( face,
                               fvar_head.axisCount,
                               ns->coords,
                               nsc );
         nsc += fvar_head.axisCount;

         FT_FRAME_EXIT();
       }

+      if ( num_instances != fvar_head.instanceCount )
+      {
+        SFNT_Service  sfnt = (SFNT_Service)face->sfnt;
+
